/* UI prototype only. No production API, auth, scheduling or data code is modified. */
const V2_KEY='pinit-ui-review-v2',TODAY='2026-10-28',FIB=[1,2,3,5,8,13,21];
let tagsV2=['커리어','pinit','개인'],trashV2=[],seriesV2=[],lifeV2=[{name:'수면',start:'23:00',duration:480},{name:'점심',start:'12:00',duration:60}],prefsV2={theme:'light',zone:'Asia/Seoul',week:'월요일',dayStart:'04:00',startNotify:true,reminder:'10',dueNotify:true,dueAt:'09:00',calibration:false},calendarMode='week',calendarMonth=new Date(2026,9,1),activeSchedule=null,statsMode='week',statsOffset=0,archiveMode=false;
let advancedV2={status:'CURRENT',deadline:'ANY',from:'',to:'',importance:0,difficulty:21,tags:[],sort:'DEADLINE_ASC'};
const baseSchedulesV2=[{id:1001,title:'하루의 우선순위 정리',date:TODAY,time:'09:00',duration:30,type:'ADMIN_TASK',state:'COMPLETED',taskId:5,description:'중요한 일부터 차근차근 정리해요.'},{id:1002,title:'한화오션 PT 면접 발표 준비',date:TODAY,time:'10:00',duration:75,type:'DEEP_WORK',state:'NOT_STARTED',taskId:1,description:'발표 자료 검토와 리허설.'},{id:1003,title:'pinit 디자인 리뷰',date:TODAY,time:'13:00',duration:45,type:'QUICK_TASK',state:'NOT_STARTED',description:'작업 카드의 정보 배치를 확인해요.'}];
tasks=initial.map(t=>({...t,tags:[t.category],previous:t.id===4?[1]:[],next:t.id===1?[4]:[],archived:false}));scheduled=baseSchedulesV2.map(s=>({...s}));
try{let state=JSON.parse(localStorage.getItem(V2_KEY));if(state){tasks=state.tasks||tasks;scheduled=state.scheduled||scheduled;tagsV2=state.tags||tagsV2;trashV2=state.trash||[];seriesV2=state.series||[];lifeV2=state.life||lifeV2;prefsV2={...prefsV2,...state.prefs};}}catch(e){}
save=function(){try{localStorage.setItem(V2_KEY,JSON.stringify({tasks,scheduled,tags:tagsV2,trash:trashV2,series:seriesV2,life:lifeV2,prefs:prefsV2}))}catch(e){toast('저장 공간을 사용할 수 없어요. 현재 화면에서는 계속 체험할 수 있어요.')}};
function syncDependenciesV2(){tasks.forEach(t=>{t.ready=(t.previous||[]).every(id=>tasks.some(p=>p.id===id&&p.done));});}
function dateKeyV2(date){let d=new Date(date);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function selectedDateV2(){return selectedDay===28?TODAY:dateKeyV2(selectedDay);}
function durationV2(n){return (Math.floor(n/60)?Math.floor(n/60)+'시간 ':'')+(n%60?n%60+'분':'')||'0분';}
function selectedOptionsV2(list,value){return list.map(([v,l])=>'<option value="'+esc(v)+'" '+(String(value)===String(v)?'selected':'')+'>'+esc(l)+'</option>').join('');}
function formFieldV2(label,input,note=''){return '<label class="field"><span>'+label+'</span>'+input+(note?'<small>'+note+'</small>':'')+'</label>';}
const TYPE_V2={DEEP_WORK:'집중 작업',QUICK_TASK:'빠른 일정',ADMIN_TASK:'행정 작업'},STATE_V2={NOT_STARTED:'미시작',IN_PROGRESS:'진행 중',SUSPENDED:'일시중지',COMPLETED:'완료'};
const sortsV2=[['DEADLINE_ASC','마감 빠른 순'],['DEADLINE_DESC','마감 늦은 순'],['IMPORTANCE_DESC','중요도 높은 순'],['DIFFICULTY_ASC','난이도 낮은 순'],['DIFFICULTY_DESC','난이도 높은 순'],['CREATED_DESC','최근 만든 순'],['TITLE_ASC','제목 가나다순']];
meter=function(value,max,type,label){return '<button class="meter '+type+'" style="--fill:'+Math.min(100,value/max*100)+'%" aria-label="'+label+' '+value+' / '+max+' · 작업 상세에서 확인" title="'+label+' '+value+' / '+max+'" onclick="openMeterV2(this)"><span>'+value+'</span></button>';};
function openMeterV2(el){let article=el.closest('[data-task-id]');if(article)openDetail(Number(article.dataset.taskId));}
taskHTML=function(t){return '<article class="task '+(t.done?'completed':'')+'" data-task-id="'+t.id+'"><button class="check '+(t.done?'checked':'')+'" aria-label="'+esc(t.title)+' '+(t.done?'완료 취소':'완료하기')+'" aria-pressed="'+t.done+'" onclick="toggleTask('+t.id+')">'+(t.done?icon('check'):'')+'</button><div class="task-copy"><button class="task-title" onclick="openDetail('+t.id+')">'+esc(t.title)+'</button><div class="task-meta">'+(t.tags||[]).map(tag=>'<span class="task-tag">#'+esc(tag)+'</span>').join(' ')+(t.repeat?'<span class="subtle-badge">반복</span>':'')+(!t.ready&&!t.done?'<span class="state-note">'+icon('link')+'이전 작업 '+(t.previous||[]).filter(id=>!tasks.find(p=>p.id===id)?.done).length+'개 남음</span>':'')+'</div></div><div class="task-side"><time class="deadline '+(t.done?'done':t.due===TODAY?'today':'')+'" datetime="'+esc(t.due||TODAY)+'">'+dueLabel(t)+'</time><div class="meters">'+meter(t.importance,9,'','중요도')+meter(t.difficulty,21,'difficulty','난이도')+'</div></div><div class="task-secondary"><details><summary>설명 · 예상 '+durationV2(t.duration)+'</summary><p>'+esc(t.description||'등록된 설명이 없어요.')+'</p></details></div></article>';};
function matchesV2(t){const f=advancedV2;return (!archiveMode||(t.done&&t.due<TODAY))&&(!query||(t.title+' '+t.description).toLowerCase().includes(query.toLowerCase()))&&(f.status==='ALL'||f.status==='CURRENT'&&(!t.done||t.due>=TODAY)||f.status==='OPEN'&&!t.done||f.status==='COMPLETED'&&t.done||f.status==='READY'&&t.ready&&!t.done||f.status==='BLOCKED'&&!t.ready&&!t.done)&&(f.deadline==='ANY'||f.deadline==='TODAY'&&t.due===TODAY||f.deadline==='OVERDUE'&&t.due<TODAY||f.deadline==='THIS_WEEK'&&t.due>='2026-10-26'&&t.due<='2026-11-01'||f.deadline==='CUSTOM'&&(!f.from||t.due>=f.from)&&(!f.to||t.due<=f.to))&&t.importance>=f.importance&&t.difficulty<=f.difficulty&&(!f.tags.length||f.tags.some(tag=>(t.tags||[]).includes(tag)));}
function sortTasksV2(list){return list.sort((a,b)=>{const f=advancedV2.sort;if(f==='IMPORTANCE_DESC')return b.importance-a.importance;if(f==='DIFFICULTY_ASC')return a.difficulty-b.difficulty;if(f==='DIFFICULTY_DESC')return b.difficulty-a.difficulty;if(f==='CREATED_DESC')return b.id-a.id;if(f==='TITLE_ASC')return a.title.localeCompare(b.title,'ko');return (a.due||'9999').localeCompare(b.due||'9999')*(f==='DEADLINE_DESC'?-1:1);});}
renderTasks=function(){syncDependenciesV2();const root=document.getElementById('taskList');if(currentView==='today'){const due=tasks.filter(t=>!t.archived&&t.due===TODAY),ready=tasks.filter(t=>!t.archived&&t.ready&&!t.done);root.innerHTML='<h3 class="today-section-title">오늘 마감 <span>'+due.length+'</span></h3><div class="task-list-section">'+(due.map(taskHTML).join('')||'<p class="empty">오늘 마감인 작업이 없어요.</p>')+'</div><h3 class="today-section-title">바로 시작할 수 있는 작업 <span>'+ready.length+'</span></h3><div class="task-list-section">'+(ready.map(taskHTML).join('')||'<p class="empty">바로 시작할 수 있는 작업이 없어요.</p>')+'</div>';}else{const list=sortTasksV2(tasks.filter(matchesV2));root.innerHTML=list.map(taskHTML).join('')||'<p class="empty">조건에 맞는 작업이 없어요.<br><button class="text-btn" style="margin:8px auto" onclick="resetFiltersV2()">검색·필터 초기화</button></p>';document.getElementById('taskCount').textContent=list.length;}
const visible=tasks.filter(t=>!t.archived),done=visible.filter(t=>t.done).length,p=Math.round(done/Math.max(visible.length,1)*100);document.getElementById('sideCount').textContent=visible.filter(t=>!t.done).length;if(currentView==='today')document.getElementById('taskCount').textContent=visible.length;document.getElementById('progressLabel').textContent=done+' / '+visible.length+' 완료';document.getElementById('progressPercent').textContent=p+'%';document.getElementById('progressBar').style.width=p+'%';document.querySelectorAll('.task-meta svg').forEach(el=>{el.style.width='11px';el.style.height='11px'});};
toggleTask=function(id){const t=tasks.find(t=>t.id===id);if(!t)return;t.done=!t.done;syncDependenciesV2();save();renderTasks();toast(t.done?'작업을 완료했어요.':'작업을 미완료로 전환했어요.',()=>toggleTask(id),'되돌리기');};
function resetFiltersV2(){query='';archiveMode=false;advancedV2={status:'CURRENT',deadline:'ANY',from:'',to:'',importance:0,difficulty:21,tags:[],sort:'DEADLINE_ASC'};if(document.getElementById('inlineSearchV2'))document.getElementById('inlineSearchV2').value='';refreshToolbarV2();renderTasks();}
function refreshToolbarV2(){let bar=document.getElementById('taskToolbarV2');if(!bar)return;bar.innerHTML='<input type="search" id="inlineSearchV2" aria-label="제목이나 설명으로 작업 검색" placeholder="제목이나 설명으로 찾기" value="'+esc(query)+'" maxlength="50" oninput="query=this.value;renderTasks()"><button class="btn" onclick="openFiltersV2()">'+icon('sort')+'필터</button><select aria-label="작업 정렬" onchange="advancedV2.sort=this.value;renderTasks()">'+selectedOptionsV2(sortsV2,advancedV2.sort)+'</select><button class="btn" onclick="archiveMode=!archiveMode;advancedV2.status=archiveMode?\'ALL\':\'CURRENT\';refreshToolbarV2();renderTasks()">'+(archiveMode?'진행 작업':'아카이브')+'</button>';document.getElementById('taskHeading').innerHTML=(archiveMode?'작업 아카이브':'작업 목록')+' <span class="number" id="taskCount"></span>';}
function openFiltersV2(){const f=advancedV2;modal(modalHead('작업 필터')+'<form onsubmit="event.preventDefault();applyFiltersV2()">'+formFieldV2('상태','<select id="filterStatusV2">'+selectedOptionsV2([['CURRENT','진행 중'],['ALL','전체'],['OPEN','미완료'],['READY','준비됨'],['BLOCKED','막힘'],['COMPLETED','완료']],f.status)+'</select>')+formFieldV2('마감','<select id="filterDeadlineV2" onchange="document.getElementById(\'filterRangeV2\').classList.toggle(\'hidden\',this.value!==\'CUSTOM\')">'+selectedOptionsV2([['ANY','전체'],['OVERDUE','지난 마감'],['TODAY','오늘'],['THIS_WEEK','이번 주'],['CUSTOM','직접']],f.deadline)+'</select>')+'<div class="form-row '+(f.deadline==='CUSTOM'?'':'hidden')+'" id="filterRangeV2">'+formFieldV2('시작 날짜','<input type="date" id="filterFromV2" value="'+f.from+'">')+formFieldV2('끝 날짜','<input type="date" id="filterToV2" value="'+f.to+'">')+'</div><div class="form-row">'+formFieldV2('최소 중요도','<select id="filterImportanceV2">'+selectedOptionsV2([[0,'전체'],...[1,2,3,4,5,6,7,8,9].map(v=>[v,v+' 이상'])],f.importance)+'</select>')+formFieldV2('최대 난이도','<select id="filterDifficultyV2">'+selectedOptionsV2(FIB.map(v=>[v,v+' 이하']),f.difficulty)+'</select>')+'</div><h3>태그 · 하나라도 포함</h3><div class="chip-row" style="margin-top:12px">'+tagsV2.map(tag=>'<label class="chip"><input type="checkbox" name="filterTagV2" value="'+esc(tag)+'" '+(f.tags.includes(tag)?'checked':'')+'>#'+esc(tag)+'</label>').join('')+'</div><div class="dialog-actions"><button type="button" class="btn" onclick="resetFiltersV2();closeModal()">초기화</button><button type="button" class="btn" onclick="openTagsV2()">태그 관리</button><button class="btn primary">필터 적용</button></div></form>');}
function applyFiltersV2(){advancedV2={...advancedV2,status:document.getElementById('filterStatusV2').value,deadline:document.getElementById('filterDeadlineV2').value,from:document.getElementById('filterFromV2').value,to:document.getElementById('filterToV2').value,importance:Number(document.getElementById('filterImportanceV2').value),difficulty:Number(document.getElementById('filterDifficultyV2').value),tags:[...document.querySelectorAll('[name=filterTagV2]:checked')].map(el=>el.value)};closeModal();renderTasks();}
openDetail=function(id){const t=tasks.find(t=>t.id===id);if(!t)return;modal(modalHead('작업 상세')+'<h3 style="font-size:20px;line-height:1.7">'+esc(t.title)+'</h3><p style="margin-top:13px">'+esc(t.description||'등록된 설명이 없어요.')+'</p><div class="detail-grid"><div><small>마감 날짜</small><strong>'+esc(t.due)+'</strong></div><div><small>예상 소요시간</small><strong>'+durationV2(t.duration)+'</strong></div><div><small>중요도</small><strong>'+t.importance+' / 9</strong></div><div><small>난이도 · 피보나치</small><strong>'+t.difficulty+' / 21</strong></div><div><small>상태</small><strong>'+(t.done?'완료':t.ready?'준비됨':'이전 작업 대기')+'</strong></div><div><small>태그</small><strong>'+esc((t.tags||[]).map(x=>'#'+x).join(' ')||'없음')+'</strong></div></div><div class="detail-section"><h3>이전·이후 작업</h3><p>이전: '+esc((t.previous||[]).map(x=>tasks.find(p=>p.id===x)?.title||'삭제된 작업').join(', ')||'없음')+'</p><p>이후: '+esc((t.next||[]).map(x=>tasks.find(p=>p.id===x)?.title||'삭제된 작업').join(', ')||'없음')+'</p><button class="btn" onclick="openTaskFormV2('+id+')">의존성 수정</button></div>'+(t.repeat?'<div class="notice">반복 작업 · '+esc(t.repeat)+'<br>반복 규칙과 종료는 설정의 반복 관리에서 확인해요.</div>':'')+'<div class="detail-actions"><button class="btn" onclick="openTaskFormV2('+id+')">수정</button><button class="btn" onclick="toggleTask('+id+');openDetail('+id+')">'+(t.done?'미완료로 전환':'완료 처리')+'</button><button class="btn primary" onclick="openAssign('+id+')">일정으로 배정</button><button class="btn danger" onclick="confirmTrashV2(\'task\','+id+')">삭제</button></div><div class="dialog-actions"><button class="text-btn" onclick="toggleArchiveV2('+id+')">'+'아카이브 기준 보기'+'</button></div>');};
function obsoleteArchiveActionV2(id){let t=tasks.find(t=>t.id===id);t.archived=!t.archived;save();closeModal();renderTasks();toast(t.archived?'작업을 보관했어요. 보관함에서 다시 볼 수 있어요.':'작업의 보관을 해제했어요.');}
function repeatFieldsV2(value=''){return '<label class="check-field"><input type="checkbox" id="repeatEnabledV2" '+(value?'checked':'')+' onchange="document.getElementById(\'repeatFieldsV2\').classList.toggle(\'hidden\',!this.checked);document.getElementById(\'dependencyFieldsV2\')?.classList.toggle(\'hidden\',this.checked)">반복</label><div id="repeatFieldsV2" class="'+(value?'':'hidden')+'"><div class="form-row">'+formFieldV2('반복 주기','<select id="repeatFrequencyV2">'+selectedOptionsV2([['매일','매일'],['매주','매주'],['매월','매월']],value||'매주')+'</select>')+formFieldV2('간격','<input type="number" id="repeatIntervalV2" min="1" max="99" value="1">')+'</div><div class="chip-row">'+['월','화','수','목','금','토','일'].map((day,i)=>'<label class="chip"><input type="checkbox" name="repeatDaysV2" value="'+i+'" '+(i===2?'checked':'')+'>'+day+'</label>').join('')+'</div>'+formFieldV2('반복 종료일 · 선택','<input type="date" id="repeatEndV2">')+'<p class="form-note">이 HTML에서는 규칙의 입력·수정 화면을 체험할 수 있어요. 회차 생성과 반복 범위 처리는 기존 서비스 로직을 유지하는 대상으로, 데모에서 실행하지 않아요.</p></div>';}
function taskDependencyFieldsV2(t){return '<details id="dependencyFieldsV2" '+(t.repeat?'class="hidden"':'')+'><summary>이전·이후 작업 선택</summary><p class="form-note">선행 작업을 모두 마치면 준비된 작업으로 전환돼요.</p>'+['previous','next'].map(mode=>'<h3 style="margin:18px 0 9px">'+(mode==='previous'?'이전 작업':'이후 작업')+'</h3><div class="chip-row">'+tasks.filter(p=>p.id!==t.id&&!p.repeat).map(p=>'<label class="chip"><input type="checkbox" name="'+mode+'V2" value="'+p.id+'" '+((t[mode]||[]).includes(p.id)?'checked':'')+'>'+esc(p.title)+'</label>').join('')+'</div>').join('')+'</details>';}
function openTaskFormV2(id){const t=tasks.find(t=>t.id===id)||{id:0,title:'',description:'',due:TODAY,importance:5,difficulty:2,duration:'',tags:[],previous:[],next:[]};modal(modalHead(id?'작업 수정':'작업 추가')+'<form onsubmit="event.preventDefault();submitTaskV2('+t.id+')">'+formFieldV2('제목','<input id="taskTitleV2" value="'+esc(t.title)+'" maxlength="100" required>')+formFieldV2('설명','<textarea id="taskDescriptionV2" rows="3" required>'+esc(t.description)+'</textarea>')+formFieldV2('마감 날짜','<input id="taskDueV2" type="date" value="'+t.due+'" required>')+'<div class="form-row">'+formFieldV2('중요도 <b id="taskImportanceValueV2">'+t.importance+'</b> / 9','<input id="taskImportanceV2" type="range" min="1" max="9" value="'+t.importance+'" oninput="document.getElementById(\'taskImportanceValueV2\').textContent=this.value">')+formFieldV2('난이도','<select id="taskDifficultyV2">'+selectedOptionsV2(FIB.map(v=>[v,String(v)]),t.difficulty)+'</select>')+'</div>'+formFieldV2('예상 소요시간 · 분 · 선택','<input type="number" min="5" max="1440" id="taskDurationV2" value="'+t.duration+'" placeholder="비워 두면 난이도에 맞춰 정해져요">')+'<h3>태그</h3><div class="chip-row" style="margin-top:10px">'+tagsV2.map(tag=>'<label class="chip"><input type="checkbox" name="taskTagV2" value="'+esc(tag)+'" '+((t.tags||[]).includes(tag)?'checked':'')+'>#'+esc(tag)+'</label>').join('')+'</div>'+formFieldV2('새 태그 · 선택','<input id="newTagV2" placeholder="태그 이름">')+repeatFieldsV2(t.repeat)+taskDependencyFieldsV2(t)+'<p class="field-error" id="taskErrorV2" role="alert"></p><div class="dialog-actions"><button type="button" class="btn" onclick="closeModal()">취소</button><button class="btn primary">'+(id?'수정 저장':'작업 추가')+'</button></div></form>');document.getElementById('taskTitleV2').focus();}
function hasCycleV2(edges){let visiting=new Set(),visited=new Set();function walk(id){if(visiting.has(id))return true;if(visited.has(id))return false;visiting.add(id);for(const to of edges.get(id)||[])if(walk(to))return true;visiting.delete(id);visited.add(id);return false;}return [...edges.keys()].some(walk);}
function submitTaskV2(id){const title=document.getElementById('taskTitleV2').value.trim(),description=document.getElementById('taskDescriptionV2').value.trim(),due=document.getElementById('taskDueV2').value;if(!title||!description||!due){document.getElementById('taskErrorV2').textContent='제목·설명·마감 날짜를 입력해 주세요.';return;}const repeat=document.getElementById('repeatEnabledV2').checked?document.getElementById('repeatFrequencyV2').value:'',previous=repeat?[]:[...document.querySelectorAll('[name=previousV2]:checked')].map(e=>Number(e.value)),next=repeat?[]:[...document.querySelectorAll('[name=nextV2]:checked')].map(e=>Number(e.value));const key=id||Date.now();let edges=new Map(tasks.map(t=>[t.id,new Set((t.next||[]).filter(x=>x!==key))]));edges.set(key,new Set(next));previous.forEach(p=>{if(!edges.has(p))edges.set(p,new Set());edges.get(p).add(key);});if(hasCycleV2(edges)){document.getElementById('taskErrorV2').textContent='이전·이후 작업이 순환해요. 연결할 작업을 다시 선택해 주세요.';return;}let taskTags=[...document.querySelectorAll('[name=taskTagV2]:checked')].map(e=>e.value),newTag=document.getElementById('newTagV2').value.trim();if(newTag){if(!tagsV2.includes(newTag))tagsV2.push(newTag);if(!taskTags.includes(newTag))taskTags.push(newTag);}const difficulty=Number(document.getElementById('taskDifficultyV2').value),durationText=document.getElementById('taskDurationV2').value;const duration=durationText?Number(durationText):difficulty*15;let old=tasks.find(t=>t.id===id);const t={...old,id:key,title,description,due,importance:Number(document.getElementById('taskImportanceV2').value),difficulty,duration,tags:taskTags,category:taskTags[0]||'개인',repeat,repeatInterval:Number(document.getElementById('repeatIntervalV2').value),repeatDays:[...document.querySelectorAll('[name=repeatDaysV2]:checked')].map(el=>Number(el.value)),repeatEnd:document.getElementById('repeatEndV2').value,previous,next,done:old?.done||false,archived:old?.archived||false,ready:!previous.length};tasks=tasks.filter(p=>p.id!==id);tasks.push(t);tasks.forEach(p=>{if(p.id===key)return;p.previous=(p.previous||[]).filter(x=>x!==key);p.next=(p.next||[]).filter(x=>x!==key);if(next.includes(p.id))p.previous.push(key);if(previous.includes(p.id))p.next.push(key);});if(repeat&&!seriesV2.some(s=>s.taskId===key))seriesV2.push({id:key,taskId:key,title,kind:'작업',frequency:repeat,interval:t.repeatInterval,days:t.repeatDays,end:t.repeatEnd,active:true});syncDependenciesV2();save();closeModal();renderTasks();toast(id?'작업을 수정했어요.':'작업을 추가했어요.');}
openAdd=function(mode='task'){if(mode==='schedule')openScheduleFormV2();else openTaskFormV2();};
openAssign=function(id){openScheduleFormV2(null,id);};
function openTagsV2(){modal(modalHead('태그 관리')+'<p>태그 이름을 바꾸면 연결된 작업에도 반영돼요.</p>'+tagsV2.map((tag,i)=>'<div class="setting-row"><input id="tagEditV2-'+i+'" aria-label="'+esc(tag)+' 이름" value="'+esc(tag)+'"><button class="text-btn" onclick="renameTagV2('+i+')">저장</button><button class="text-btn danger" onclick="deleteTagV2('+i+')">삭제</button></div>').join('')+'<form onsubmit="event.preventDefault();addTagV2()">'+formFieldV2('새 태그','<input id="tagAddV2" required maxlength="30">')+'<div class="dialog-actions"><button class="btn primary">태그 추가</button></div></form>');}
function renameTagV2(i){let value=document.getElementById('tagEditV2-'+i).value.trim(),old=tagsV2[i];if(!value||tagsV2.some((t,j)=>j!==i&&t===value)){toast('중복되지 않는 태그 이름을 입력해 주세요.');return;}tagsV2[i]=value;tasks.forEach(t=>t.tags=(t.tags||[]).map(x=>x===old?value:x));advancedV2.tags=advancedV2.tags.map(x=>x===old?value:x);save();renderTasks();openTagsV2();toast('태그 이름을 바꿨어요.');}
function deleteTagV2(i){let old=tagsV2[i];tagsV2.splice(i,1);tasks.forEach(t=>t.tags=(t.tags||[]).filter(x=>x!==old));advancedV2.tags=advancedV2.tags.filter(x=>x!==old);save();renderTasks();openTagsV2();toast('태그를 삭제했어요. 작업은 유지돼요.');}
function addTagV2(){let tag=document.getElementById('tagAddV2').value.trim();if(tag&&!tagsV2.includes(tag)){tagsV2.push(tag);save();openTagsV2();toast('태그를 추가했어요.');}else toast('중복되지 않는 태그 이름을 입력해 주세요.');}
function confirmTrashV2(kind,id){let item=(kind==='task'?tasks:scheduled).find(x=>x.id===id);if(!item)return;modal(modalHead('휴지통으로 이동')+'<p><strong>'+esc(item.title)+'</strong></p><p>휴지통에서 다시 복원할 수 있어요. 실제 서비스의 보관 기간과 반복 삭제 범위 정책은 그대로 유지하는 대상입니다.</p><div class="dialog-actions"><button class="btn" onclick="closeModal()">취소</button><button class="btn danger" onclick="moveTrashV2(\''+kind+'\','+id+')">휴지통으로 이동</button></div>');}
function moveTrashV2(kind,id){const source=kind==='task'?tasks:scheduled,item=source.find(t=>t.id===id);trashV2.push({kind,item,deletedAt:TODAY});if(kind==='task'){tasks=tasks.filter(t=>t.id!==id);tasks.forEach(t=>{t.previous=(t.previous||[]).filter(x=>x!==id);t.next=(t.next||[]).filter(x=>x!==id);});}else scheduled=scheduled.filter(t=>t.id!==id);if(activeSchedule===id)activeSchedule=null;save();closeModal();renderTasks();renderTimeline();renderPlayerV2();toast('휴지통으로 옮겼어요.',()=>restoreTrashV2(kind,id),'되돌리기');}
function restoreTrashV2(kind,id){let entry=trashV2.find(t=>t.kind===kind&&t.item.id===id);if(!entry)return;(kind==='task'?tasks:scheduled).push(entry.item);trashV2=trashV2.filter(t=>t!==entry);if(kind==='task'){tasks.forEach(t=>{if((entry.item.previous||[]).includes(t.id)&&!(t.next||[]).includes(id))t.next=[...(t.next||[]),id];if((entry.item.next||[]).includes(t.id)&&!(t.previous||[]).includes(id))t.previous=[...(t.previous||[]),id];});}save();renderTasks();renderTimeline();if(currentView==='trash')renderTrashV2();toast('복원했어요.');}
function openScheduleFormV2(id,taskId){const task=tasks.find(t=>t.id===taskId),s=scheduled.find(t=>t.id===id)||{id:0,title:task?.title||'',description:task?.description||'',date:selectedDateV2(),time:'14:00',duration:task?.duration||30,type:'DEEP_WORK',taskId:taskId||null};modal(modalHead(id?'일정 수정':taskId?'작업을 일정으로 배정':'일정 추가')+'<form onsubmit="event.preventDefault();submitScheduleV2('+s.id+','+(s.taskId||'null')+')">'+formFieldV2('일정 제목','<input id="scheduleTitleV2" required maxlength="100" value="'+esc(s.title)+'">')+formFieldV2('설명','<textarea id="scheduleDescriptionV2">'+esc(s.description||'')+'</textarea>')+formFieldV2('일정 타입','<select id="scheduleTypeV2">'+selectedOptionsV2(Object.entries(TYPE_V2),s.type)+'</select>')+formFieldV2('시작 시간','<input id="scheduleDateV2" type="datetime-local" required value="'+s.date+'T'+s.time+'">')+formFieldV2('계획 길이 · 분 · 선택','<input id="scheduleDurationV2" type="number" min="5" max="1440" value="'+s.duration+'" placeholder="비워 두면 30분">')+repeatFieldsV2(s.repeat)+'<p class="field-error" id="scheduleErrorV2" role="alert"></p><div class="dialog-actions"><button type="reset" class="btn">초기화</button><button class="btn primary">'+(id?'수정 저장':taskId?'일정으로 배정':'일정 저장')+'</button></div></form>');document.getElementById('scheduleTitleV2').focus();}
function submitScheduleV2(id,taskId){let title=document.getElementById('scheduleTitleV2').value.trim(),dateTime=document.getElementById('scheduleDateV2').value;if(!title||!dateTime){document.getElementById('scheduleErrorV2').textContent='제목과 시작 시간을 입력해 주세요.';return;}let original=scheduled.find(s=>s.id===id),repeat=document.getElementById('repeatEnabledV2').checked?document.getElementById('repeatFrequencyV2').value:'',key=id||Date.now();const s={...original,id:key,taskId,title,description:document.getElementById('scheduleDescriptionV2').value,date:dateTime.slice(0,10),time:dateTime.slice(11,16),duration:Number(document.getElementById('scheduleDurationV2').value)||30,type:document.getElementById('scheduleTypeV2').value,state:original?.state||'NOT_STARTED',repeat};scheduled=scheduled.filter(p=>p.id!==id);scheduled.push(s);if(repeat&&!seriesV2.some(p=>p.scheduleId===key))seriesV2.push({id:key,scheduleId:key,title,kind:'일정',frequency:repeat,interval:Number(document.getElementById('repeatIntervalV2').value),days:[...document.querySelectorAll('[name=repeatDaysV2]:checked')].map(el=>Number(el.value)),end:document.getElementById('repeatEndV2').value,active:true});save();closeModal();selectedDay=new Date(s.date+'T12:00:00').getTime();renderWeek();renderTimeline();toast(id?'일정을 수정했어요.':'일정을 추가했어요.');}
function openScheduleDetailV2(id){let s=scheduled.find(x=>x.id===id);if(!s)return;modal(modalHead('일정 상세')+'<h3 style="font-size:19px;line-height:1.7">'+esc(s.title)+'</h3><p style="margin-top:12px">'+esc(s.description||'등록된 설명이 없어요.')+'</p><div class="detail-grid"><div><small>시작</small><strong>'+s.date+' '+s.time+'</strong></div><div><small>계획 길이</small><strong>'+durationV2(s.duration)+'</strong></div><div><small>상태</small><strong>'+STATE_V2[s.state]+'</strong></div><div><small>일정 타입</small><strong>'+TYPE_V2[s.type]+'</strong></div></div><div class="detail-section"><h3>이전·이후 일정</h3><p>'+esc((s.previous||[]).map(id=>scheduled.find(p=>p.id===id)?.title||'삭제된 일정').join(', ')||'연결된 이전 일정이 없어요.')+'</p><button class="btn" onclick="openScheduleDependenciesV2('+s.id+')">일정 의존성 관리</button>'+(s.taskId?'<button class="btn" style="margin-left:8px" onclick="openDetail('+s.taskId+')">연결된 작업 보기</button>':'')+'</div><div class="detail-actions"><button class="btn" onclick="openScheduleFormV2('+id+')">수정</button><button class="btn" onclick="openMoveV2('+id+')">시간·날짜 이동</button><button class="btn primary" onclick="changeStateV2('+id+',\''+(s.state==='IN_PROGRESS'?'SUSPENDED':'IN_PROGRESS')+'\');openScheduleDetailV2('+id+')">'+(s.state==='IN_PROGRESS'?'일시중지':'시작 / 재개')+'</button><button class="btn" onclick="changeStateV2('+id+',\'COMPLETED\');openScheduleDetailV2('+id+')">완료</button><button class="btn" onclick="changeStateV2('+id+',\'NOT_STARTED\');openScheduleDetailV2('+id+')">취소 · 미시작으로</button><button class="btn danger" onclick="confirmTrashV2(\'schedule\','+id+')">삭제</button></div>');}
function openScheduleDependenciesV2(id){let s=scheduled.find(x=>x.id===id);modal(modalHead('일정 의존성 관리')+'<p>먼저 끝내야 하는 일정을 선택하세요.</p><form onsubmit="event.preventDefault();saveScheduleDependenciesV2('+id+')"><div class="chip-row" style="margin-top:17px">'+scheduled.filter(p=>p.id!==id).map(p=>'<label class="chip"><input type="checkbox" name="schedulePreviousV2" value="'+p.id+'" '+((s.previous||[]).includes(p.id)?'checked':'')+'>'+esc(p.title)+'</label>').join('')+'</div><p class="field-error" id="scheduleDependencyErrorV2"></p><div class="dialog-actions"><button class="btn primary">연결 저장</button></div></form>');}
function saveScheduleDependenciesV2(id){let prev=[...document.querySelectorAll('[name=schedulePreviousV2]:checked')].map(el=>Number(el.value)),edges=new Map(scheduled.map(s=>[s.id,new Set(s.id===id?prev:s.previous||[])]));if(hasCycleV2(edges)){document.getElementById('scheduleDependencyErrorV2').textContent='순환 연결을 만들 수 없어요.';return;}scheduled.find(s=>s.id===id).previous=prev;save();openScheduleDetailV2(id);}
function changeStateV2(id,state){let s=scheduled.find(x=>x.id===id);if(!s)return;if(state==='IN_PROGRESS'&&(s.previous||[]).some(id=>scheduled.find(p=>p.id===id)?.state!=='COMPLETED')){toast('먼저 연결된 이전 일정을 완료해 주세요.');return;}if(s.state==='IN_PROGRESS'&&s.startedAt)s.elapsed=(s.elapsed||0)+Math.floor((Date.now()-s.startedAt)/1000);s.state=state;s.startedAt=state==='IN_PROGRESS'?Date.now():null;if(state==='IN_PROGRESS')activeSchedule=id;else if(activeSchedule===id)activeSchedule=null;save();renderTimeline();renderPlayerV2();toast('일정 상태를 '+STATE_V2[state]+'으로 바꿨어요.');}
function renderPlayerV2(){let root=document.getElementById('playerV2'),s=scheduled.find(x=>x.id===activeSchedule);if(!s){root.innerHTML='';return;}root.innerHTML='<div class="player"><button class="player-title" onclick="openScheduleDetailV2('+s.id+')"><small>진행 중인 일정</small>'+esc(s.title)+'</button><time id="elapsedV2">00:00</time><button class="btn" onclick="changeStateV2('+s.id+',\'SUSPENDED\')">일시중지</button><button class="btn primary" onclick="changeStateV2('+s.id+',\'COMPLETED\')">완료</button></div>';tickV2();}
function tickV2(){let label=document.getElementById('elapsedV2'),s=scheduled.find(x=>x.id===activeSchedule);if(label&&s){let seconds=(s.elapsed||0)+(s.startedAt?Math.floor((Date.now()-s.startedAt)/1000):0);label.textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');}}
setInterval(tickV2,1000);
function openMoveV2(id){let s=scheduled.find(x=>x.id===id);modal(modalHead('일정 시간 이동')+'<p>'+esc(s.title)+'</p><form onsubmit="event.preventDefault();moveScheduleV2('+id+',document.getElementById(\'moveDateV2\').value)">'+formFieldV2('날짜 및 시각','<input id="moveDateV2" type="datetime-local" value="'+s.date+'T'+s.time+'" required>')+'<div class="dialog-actions"><button class="btn" type="button" onclick="shiftDayV2('+id+',-1)">전날</button><button class="btn" type="button" onclick="shiftDayV2('+id+',1)">다음날</button><button class="btn primary">시간 이동</button></div></form>');}
function shiftDayV2(id,n){let s=scheduled.find(x=>x.id===id),date=new Date(s.date+'T12:00:00');date.setDate(date.getDate()+n);moveScheduleV2(id,dateKeyV2(date)+'T'+s.time);}
function moveScheduleV2(id,value){let s=scheduled.find(x=>x.id===id);s.date=value.slice(0,10);s.time=value.slice(11,16);save();closeModal();renderTimeline();toast('일정을 '+s.date+' '+s.time+'으로 옮겼어요.');}
let draggedScheduleV2=null;function dropScheduleV2(event,id){event.preventDefault();if(!draggedScheduleV2||draggedScheduleV2===id)return;let source=scheduled.find(s=>s.id===draggedScheduleV2),target=scheduled.find(s=>s.id===id);[source.time,target.time]=[target.time,source.time];save();renderTimeline();toast('두 일정의 시작 시각을 바꿨어요.');draggedScheduleV2=null;}
function scheduleHTMLV2(s){return '<article class="schedule-row" data-schedule-id="'+s.id+'" ondragover="event.preventDefault()" ondrop="dropScheduleV2(event,'+s.id+')"><button draggable="true" class="schedule-time" aria-label="'+esc(s.title)+' '+s.time+' · 시간 이동" ondragstart="draggedScheduleV2='+s.id+';event.dataTransfer.setData(\'text/plain\',String('+s.id+'))" onclick="openMoveV2('+s.id+')">'+s.time+'<small>시간 이동</small></button><div class="schedule-main" data-state="'+s.state+'"><div class="schedule-title-line"><button class="icon-btn" aria-label="'+STATE_V2[s.state]+' · '+(s.state==='COMPLETED'?'완료 취소':'시작')+'" onclick="changeStateV2('+s.id+',\''+(s.state==='COMPLETED'?'NOT_STARTED':'IN_PROGRESS')+'\')">'+icon(s.state==='COMPLETED'?'check':'play')+'</button><button class="schedule-title" onclick="openScheduleDetailV2('+s.id+')">'+esc(s.title)+'</button></div><div class="schedule-caption"><span>'+TYPE_V2[s.type]+'</span><span>'+durationV2(s.duration)+'</span><span>'+STATE_V2[s.state]+'</span>'+(s.repeat?'<span>반복</span>':'')+'</div><div class="schedule-actions">'+(s.state==='NOT_STARTED'?'<button class="primary" onclick="changeStateV2('+s.id+',\'IN_PROGRESS\')">시작</button><button onclick="changeStateV2('+s.id+',\'COMPLETED\')">즉시 완료</button>':s.state==='IN_PROGRESS'?'<button onclick="changeStateV2('+s.id+',\'SUSPENDED\')">일시중지</button><button class="primary" onclick="changeStateV2('+s.id+',\'COMPLETED\')">완료</button>':s.state==='SUSPENDED'?'<button class="primary" onclick="changeStateV2('+s.id+',\'IN_PROGRESS\')">재개</button><button onclick="changeStateV2('+s.id+',\'COMPLETED\')">완료</button>':'<button onclick="changeStateV2('+s.id+',\'NOT_STARTED\')">완료 취소</button>')+'<button class="more" onclick="openScheduleDetailV2('+s.id+')">상세</button><button class="danger" onclick="confirmTrashV2(\'schedule\','+s.id+')" aria-label="'+esc(s.title)+' 삭제">삭제</button></div></div></article>';}
renderTimeline=function(){const key=selectedDateV2(),list=scheduled.filter(s=>s.date===key).sort((a,b)=>a.time.localeCompare(b.time)),overdue=scheduled.filter(s=>s.date<TODAY&&s.state!=='COMPLETED');document.getElementById('timeline').className='schedule-list';document.getElementById('timeline').innerHTML=(overdue.length?'<div class="overdue-note">미완료 일정 '+overdue.length+'개<button onclick="selectedDay=new Date(\''+overdue[0].date+'T12:00:00\').getTime();renderWeek();renderTimeline()">해당 날짜 보기</button></div>':'')+(list.map(scheduleHTMLV2).join('')||'<div class="empty">등록된 일정이 없어요.<br><button class="btn" style="margin-top:14px" onclick="openScheduleFormV2()">일정 추가</button></div>');document.getElementById('scheduleTotal').textContent=key.slice(5).replace('-','/')+' · '+list.length+'개 · '+durationV2(list.reduce((n,s)=>n+s.duration,0));};
renderWeek=function(){const root=document.getElementById('week');root.className=calendarMode==='month'?'month-calendar':'week';document.getElementById('calendarDate').textContent=calendarMode==='month'?calendarMonth.getFullYear()+'년 '+(calendarMonth.getMonth()+1)+'월':new Date(2026,9,26+weekOffset).getFullYear()+'년 '+(new Date(2026,9,26+weekOffset).getMonth()+1)+'월';if(calendarMode==='month'){const y=calendarMonth.getFullYear(),m=calendarMonth.getMonth(),offset=(new Date(y,m,1).getDay()+6)%7,days=new Date(y,m+1,0).getDate();root.innerHTML=['월','화','수','목','금','토','일'].map(d=>'<span>'+d+'</span>').join('')+Array.from({length:offset},()=>'<span></span>').join('')+Array.from({length:days},(_,i)=>{let date=new Date(y,m,i+1),key=dateKeyV2(date);return '<button class="'+(selectedDateV2()===key?'active ':'')+(scheduled.some(s=>s.date===key)?'has-events':'')+'" aria-label="'+key+'" onclick="selectDay('+date.getTime()+')">'+(i+1)+'</button>';}).join('');}else{const start=new Date(2026,9,26+weekOffset);root.innerHTML=Array.from({length:7},(_,i)=>{let d=new Date(start);d.setDate(d.getDate()+i);return '<button class="day '+(selectedDateV2()===dateKeyV2(d)?'active':'')+'" aria-label="'+dateKeyV2(d)+'" onclick="selectDay('+d.getTime()+')"><span>'+['월','화','수','목','金','토','일'][i].replace('金','금')+'</span><strong>'+d.getDate()+'</strong><span class="day-dot" style="opacity:'+(scheduled.some(s=>s.date===dateKeyV2(d))?1:0)+'"></span></button>';}).join('');}document.querySelectorAll('[data-calendar-mode]').forEach(b=>b.classList.toggle('active',b.dataset.calendarMode===calendarMode));};
changeWeek=function(n){if(calendarMode==='month'){calendarMonth.setMonth(calendarMonth.getMonth()+(n<0?-1:1));selectedDay=new Date(calendarMonth).getTime();}else{weekOffset+=n;selectedDay=new Date(2026,9,26+weekOffset).getTime();}renderWeek();renderTimeline();};
resetDay=function(){selectedDay=28;weekOffset=0;calendarMonth=new Date(2026,9,1);renderWeek();renderTimeline();};
function calendarModeV2(mode){calendarMode=mode;renderWeek();}
let draftPlanV2=[];
openPlanner=function(){let date=selectedDateV2(),minute=7*60;const occupied=[...scheduled.filter(s=>s.date===date).map(s=>{let [h,m]=s.time.split(':').map(Number);return [h*60+m,h*60+m+s.duration];}),...lifeV2.map(s=>{let [h,m]=s.start.split(':').map(Number),start=h*60+m;return [start,Math.min(1440,start+s.duration)];})];draftPlanV2=tasks.filter(t=>!t.done&&!t.archived&&t.ready&&!scheduled.some(s=>s.taskId===t.id&&s.date===date)).sort((a,b)=>b.importance-a.importance).map(t=>{for(let n=0;n<100&&occupied.some(([a,b])=>minute<b&&minute+t.duration>a);n++){let conflict=occupied.find(([a,b])=>minute<b&&minute+t.duration>a);minute=conflict[1]+15;}let result={taskId:t.id,title:t.title,date,time:String(Math.floor(minute/60)).padStart(2,'0')+':'+String(minute%60).padStart(2,'0'),duration:t.duration,type:'DEEP_WORK',selected:minute+t.duration<=23*60};minute+=t.duration+15;return result;});renderPlannerV2();};
function renderPlannerV2(){modal(modalHead('하루 계획')+'<p>기존 기능의 계획일·마감 범위·제안 블록 검토·선택 적용 화면을 유지합니다.</p><div class="form-row">'+formFieldV2('계획일','<input type="date" id="planDateV2" value="'+selectedDateV2()+'">')+formFieldV2('마감 범위','<select id="planRangeV2"><option value="1">1일</option><option value="3">3일</option><option value="7" selected>7일</option><option value="14">14일</option></select>')+'</div><div class="entry-group"><button class="btn" onclick="regeneratePlanV2()">제안 새로고침</button><button class="text-btn" onclick="draftPlanV2.forEach(s=>s.selected=true);renderPlannerV2()">모두 선택</button><button class="text-btn" onclick="draftPlanV2.forEach(s=>s.selected=false);renderPlannerV2()">모두 해제</button></div><h3 style="margin-top:22px">제안 블록 '+draftPlanV2.length+'개</h3>'+draftPlanV2.map((s,i)=>'<div class="detail-section"><label class="check-field"><input type="checkbox" '+(s.selected?'checked':'')+' onchange="draftPlanV2['+i+'].selected=this.checked">'+esc(s.title)+'</label><div class="form-row">'+formFieldV2('시작','<input aria-label="'+esc(s.title)+' 시작" type="time" value="'+s.time+'" onchange="draftPlanV2['+i+'].time=this.value">')+formFieldV2('유형','<select onchange="draftPlanV2['+i+'].type=this.value">'+selectedOptionsV2(Object.entries(TYPE_V2),s.type)+'</select>')+'</div><p>계획 길이 '+durationV2(s.duration)+'</p></div>').join('')+'<div class="notice">HTML에서는 화면 검토를 위한 간단한 배치만 제공합니다. 실제 자동 계획·시간 보정·제약 검증은 기존 서비스의 로직을 그대로 사용하는 대상입니다.</div><div class="dialog-actions"><button class="btn" onclick="closeModal();navigate(\'routines\')">생활 시간 설정</button><button class="btn primary" onclick="applyPlanV2()">선택한 일정 적용</button></div>');}
function regeneratePlanV2(){let date=document.getElementById('planDateV2').value,range=Number(document.getElementById('planRangeV2').value),end=new Date(date+'T12:00:00');end.setDate(end.getDate()+range);selectedDay=new Date(date+'T12:00:00').getTime();openPlanner();draftPlanV2=draftPlanV2.filter(s=>{let t=tasks.find(t=>t.id===s.taskId);return t.due<=dateKeyV2(end);});renderPlannerV2();}
function applyPlanV2(){let chosen=draftPlanV2.filter(s=>s.selected);if(!chosen.length){toast('적용할 블록을 선택해 주세요.');return;}for(const s of chosen){if(!s.time||!/^([01]\d|2[0-3]):[0-5]\d$/.test(s.time)){toast('유효한 시작 시간을 입력해 주세요.');return;}}let now=Date.now();scheduled.push(...chosen.map((s,i)=>({...s,id:now+i,state:'NOT_STARTED',description:tasks.find(t=>t.id===s.taskId)?.description||''})));save();closeModal();renderTimeline();toast(chosen.length+'개 일정을 적용했어요.');}
function serviceOnlyV2(title){modal(modalHead(title)+'<p>기존 서비스에서 제공하는 기능입니다. 디자인 검토용 HTML에는 계정 인증과 서버 연결을 넣지 않았습니다.</p><div class="notice">실제 적용 시 기존 화면·API·권한·처리 로직을 그대로 연결합니다. 이 데모에서 계정, 알림 권한, 연결된 앱의 상태를 바꾸지 않습니다.</div><div class="dialog-actions"><button class="btn primary" onclick="closeModal()">확인</button></div>');}
function settingsRowV2(title,note,control){return '<div class="setting-row"><span>'+title+(note?'<small>'+note+'</small>':'')+'</span>'+control+'</div>';}
function settingLinkV2(title,note,view){return '<button class="setting-row settings-link" onclick="navigate(\''+view+'\')"><span>'+title+'<small>'+note+'</small></span>'+icon('right')+'</button>';}
function prefCheckV2(key,label){return '<input type="checkbox" aria-label="'+label+' 데모 설정" '+(prefsV2[key]?'checked':'')+' onchange="prefsV2.'+key+'=this.checked;save()">';}
function renderSettingsV2(){document.getElementById('alternatePanel').innerHTML='<div class="settings-grid"><section class="settings-section"><h2>자동 계획</h2>'+settingLinkV2('생활 시간','수면·식사·고정 생활 시간을 계획에 반영','routines')+settingLinkV2('반복 관리','반복 작업·일정의 규칙 수정과 종료','recurrences')+'</section><section class="settings-section"><h2>표시 및 기준 정보</h2>'+settingsRowV2('화면 테마','밝게·어둡게·시스템','<select aria-label="테마" onchange="prefsV2.theme=this.value;applyThemeV2();save()">'+selectedOptionsV2([['light','밝게'],['dark','어둡게'],['system','시스템']],prefsV2.theme)+'</select>')+settingsRowV2('시간대','기존 서비스의 기준 정보','<select aria-label="시간대" onchange="prefsV2.zone=this.value;save()">'+selectedOptionsV2([['Asia/Seoul','Asia/Seoul'],['Asia/Tokyo','Asia/Tokyo'],['UTC','UTC'],['America/New_York','America/New_York']],prefsV2.zone)+'</select>')+settingsRowV2('하루 시작','기존 날짜 구분 기준 유지','<input aria-label="하루 시작 시각" type="time" value="'+prefsV2.dayStart+'" onchange="prefsV2.dayStart=this.value;save()">')+settingsRowV2('주간 기준','통계 기준 요일','<select aria-label="주간 기준" onchange="prefsV2.week=this.value;save()">'+selectedOptionsV2([['월요일','월요일'],['일요일','일요일']],prefsV2.week)+'</select>')+'</section><section class="settings-section"><h2>알림 설정</h2>'+settingsRowV2('일정 시작 알림','데모에서는 값만 저장합니다',prefCheckV2('startNotify','일정 시작 알림'))+settingsRowV2('일정 시작 전 알림','','<select aria-label="일정 시작 전 알림" onchange="prefsV2.reminder=this.value;save()">'+selectedOptionsV2([['off','끄기'],['5','5분 전'],['10','10분 전'],['15','15분 전'],['30','30분 전']],prefsV2.reminder)+'</select>')+settingsRowV2('작업 마감일 알림','알림 수신 시각과 활성화 상태 유지',prefCheckV2('dueNotify','작업 마감일 알림')+'<input type="time" aria-label="마감일 알림 시각" value="'+prefsV2.dueAt+'" onchange="prefsV2.dueAt=this.value;save()">')+'<button class="setting-row settings-link" onclick="serviceOnlyV2(\'브라우저 푸시 알림\')"><span>브라우저 푸시 알림<small>권한 확인과 구독 설정</small></span>'+icon('right')+'</button></section><section class="settings-section"><h2>AI 연결 (MCP)</h2><p class="subtitle">MCP 서버 안내·연결된 앱·활동 기록을 기존대로 유지합니다.</p><button class="setting-row settings-link" onclick="serviceOnlyV2(\'AI 연결 (MCP)\')"><span>MCP 연결 안내<small>서버 주소·연결된 앱·연결 해제</small></span>'+icon('right')+'</button><button class="setting-row settings-link" onclick="serviceOnlyV2(\'MCP 활동 기록\')"><span>활동 기록</span>'+icon('right')+'</button></section><section class="settings-section"><h2>휴지통 및 도움말</h2>'+settingLinkV2('휴지통','삭제한 작업·일정 복원','trash')+'<button class="setting-row settings-link" onclick="openGuide()"><span>온보딩·사용 안내<small>기존 진입 경로 유지</small></span>'+icon('right')+'</button></section><section class="settings-section"><h2>계정</h2><p class="subtitle">인증과 계정 기능은 기존 서비스에서 처리합니다.</p>'+['비밀번호 변경','로그아웃','회원 탈퇴'].map(t=>'<button class="setting-row settings-link '+(t==='회원 탈퇴'?'danger':'')+'" onclick="serviceOnlyV2(\''+t+'\')"><span>'+t+'</span>'+icon('right')+'</button>').join('')+'</section></div><div class="feature-note"><span>이 화면의 설정은 UI 데모에만 저장됩니다. 실제 계정의 기준 정보나 알림은 바뀌지 않습니다.</span></div>';}
function applyThemeV2(){let mode=prefsV2.theme==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):prefsV2.theme;document.documentElement.dataset.prototypeTheme=mode;}
renderRoutines=function(){document.getElementById('alternatePanel').innerHTML='<h2 style="font-size:16px">생활 시간</h2><p class="subtitle">수면·식사처럼 작업을 배치하지 않을 시간을 설정합니다.<br>완료할 일이 반복된다면 <button class="text-btn" style="display:inline;color:var(--blue)" onclick="navigate(\'recurrences\')">반복 관리</button>를 이용하세요.</p><div id="lifeRowsV2">'+lifeV2.map((s,i)=>'<div class="routine-item"><label class="field routine-name"><span>이름</span><input aria-label="생활 시간 이름 '+(i+1)+'" value="'+esc(s.name)+'" onchange="lifeV2['+i+'].name=this.value;save()"></label><label class="field"><span>시작</span><input aria-label="'+esc(s.name)+' 시작" type="time" value="'+s.start+'" onchange="lifeV2['+i+'].start=this.value;save()"></label><label class="field"><span>길이 · 분</span><input aria-label="'+esc(s.name)+' 길이" type="number" min="5" max="1440" value="'+s.duration+'" onchange="lifeV2['+i+'].duration=Number(this.value);save()"></label><button class="icon-btn danger" aria-label="'+esc(s.name)+' 삭제" onclick="lifeV2.splice('+i+',1);save();renderRoutines()">'+icon('close')+'</button></div>').join('')+'</div><div class="dialog-actions"><button class="btn" onclick="lifeV2.push({name:\'생활 시간\',start:\'18:00\',duration:60});save();renderRoutines()">생활 시간 추가</button><button class="btn primary" onclick="save();toast(\'생활 시간을 저장했어요.\')">저장</button></div><div class="notice">요일별 변형·특정 날짜 예외·반복 회차 생성은 실제 서비스의 기존 처리 범위를 유지합니다. 이 HTML에서는 기본 시간 설정의 배치를 체험합니다.</div><button class="btn" style="margin-top:16px" onclick="openLifeOverrideV2()">특정 날짜 예외</button>';};
function openLifeOverrideV2(){modal(modalHead('특정 날짜 생활 시간 예외')+'<p>기존 예외 설정의 입력 경로입니다. HTML에서는 화면만 검토할 수 있습니다.</p>'+formFieldV2('예외 날짜','<input type="date" value="'+TODAY+'">')+formFieldV2('대상','<select>'+lifeV2.map(s=>'<option>'+esc(s.name)+'</option>').join('')+'</select>')+formFieldV2('예외 시작','<input type="time" value="12:30">')+'<div class="dialog-actions"><button class="btn primary" onclick="closeModal();toast(\'예외 입력 화면을 확인했어요. 실제 저장은 서비스에서 처리합니다.\')">화면 확인</button></div>');}
function renderRecurrencesV2(){document.getElementById('alternatePanel').innerHTML='<div class="panel-head" style="padding:0 0 20px"><h2>반복 관리</h2><div class="entry-group"><button class="btn" onclick="openTaskFormV2()">작업 추가</button><button class="btn" onclick="openScheduleFormV2()">일정 추가</button></div></div><p class="subtitle">생성·수정 폼에서 반복을 켜면 여기에 표시됩니다.</p>'+(seriesV2.map(s=>'<div class="setting-row"><span>'+esc(s.title)+'<small>'+s.kind+' · '+s.frequency+' · '+(s.active?'진행 중':'종료')+'</small></span><button class="text-btn" onclick="openSeriesV2('+s.id+')">규칙 수정</button><button class="text-btn danger" onclick="endSeriesV2('+s.id+')">종료</button></div>').join('')||'<p class="empty">아직 등록된 반복이 없어요.<br>작업·일정 추가 화면에서 반복을 설정해보세요.</p>')+'<div class="notice">회차 생성, 이번만·이후·전체 수정·삭제는 기존 서비스 로직의 유지 대상입니다. HTML에서 서버 동작을 대체하지 않습니다.</div>';}
function openSeriesV2(id){let s=seriesV2.find(s=>s.id===id);modal(modalHead('반복 규칙 수정')+'<form onsubmit="event.preventDefault();saveSeriesV2('+id+')">'+formFieldV2('이름','<input id="seriesTitleV2" value="'+esc(s.title)+'" required>')+repeatFieldsV2(s.frequency)+'<div class="dialog-actions"><button class="btn primary">규칙 저장</button></div></form>');}
function saveSeriesV2(id){let s=seriesV2.find(s=>s.id===id);s.title=document.getElementById('seriesTitleV2').value.trim();s.frequency=document.getElementById('repeatFrequencyV2').value;s.interval=Number(document.getElementById('repeatIntervalV2').value);s.days=[...document.querySelectorAll('[name=repeatDaysV2]:checked')].map(el=>Number(el.value));s.end=document.getElementById('repeatEndV2').value;save();closeModal();renderRecurrencesV2();toast('데모의 반복 규칙을 수정했어요.');}
function endSeriesV2(id){let s=seriesV2.find(s=>s.id===id);s.active=false;save();renderRecurrencesV2();toast('데모의 반복을 종료했어요.');}
function renderTrashV2(){document.getElementById('alternatePanel').innerHTML='<h2 style="font-size:16px">휴지통</h2><p class="subtitle">기존 복원 경로를 유지합니다. 실제 서비스의 30일 보관 정책은 변경하지 않습니다.</p>'+(trashV2.map(({kind,item})=>'<div class="setting-row"><span>'+esc(item.title)+'<small>'+(kind==='task'?'작업':'일정')+'</small></span><button class="btn" onclick="restoreTrashV2(\''+kind+'\','+item.id+')">복원</button></div>').join('')||'<p class="empty">휴지통이 비어 있어요.</p>');}
renderStats=function(){const counts=scheduled.filter(s=>s.state==='COMPLETED'),total=counts.reduce((n,s)=>n+s.duration,0),n=tasks.filter(t=>t.done).length;document.getElementById('alternatePanel').innerHTML='<div class="stat-tabs">'+[['week','주간'],['month','월간'],['recurrence','반복']].map(([value,title])=>'<button class="btn '+(statsMode===value?'active':'')+'" onclick="statsMode=\''+value+'\';statsOffset=0;renderStats()">'+title+'</button>').join('')+'<div class="stat-period"><button class="mini-btn" aria-label="이전 기간" onclick="statsOffset--;renderStats()">'+icon('left')+'</button><span>'+(statsOffset?statsOffset+' 기간':'현재 기간')+'</span><button class="mini-btn" aria-label="다음 기간" '+(statsOffset>=0?'disabled':'')+' onclick="statsOffset++;renderStats()">'+icon('right')+'</button><button class="text-btn" onclick="renderStats();toast(\'데모 기록을 새로고침했어요.\')">새로고침</button></div></div><h2 style="font-size:16px">'+(statsMode==='week'?'주간 통계':statsMode==='month'?'월간 통계':'반복 통계')+'</h2><p class="subtitle">기간별 상세 지표·추세·반복 통계는 기존 집계 방식을 그대로 유지합니다.</p><div class="stats-grid"><div><div class="stat-value">'+(statsOffset?0:n)+'<small>개</small></div><div class="stat-label">완료한 작업</div></div><div><div class="stat-value">'+(statsOffset?0:total)+'<small>분</small></div><div class="stat-label">완료 일정의 계획 시간 · 데모</div></div><div><div class="stat-value">'+(statsOffset?0:counts.length)+'<small>개</small></div><div class="stat-label">완료한 일정</div></div></div><div class="metric-breakdown">'+Object.entries(TYPE_V2).map(([key,label])=>'<div>'+label+'<strong>'+durationV2(statsOffset?0:counts.filter(s=>s.type===key).reduce((n,s)=>n+s.duration,0))+'</strong></div>').join('')+'</div>'+(statsMode==='recurrence'?'<div class="detail-section"><h3>반복 규칙</h3><p class="subtitle">현재 등록 '+seriesV2.length+'개 · 진행 중 '+seriesV2.filter(s=>s.active).length+'개</p><button class="btn" style="margin-top:15px" onclick="navigate(\'recurrences\')">반복 관리</button></div>':'<div class="detail-section"><h3>기간 요약 및 추세</h3><p class="subtitle">실제 기록의 추세·기간 비교·도넛·주간 차트는 기존 통계 API 연결 대상입니다. 데모 수치를 실제 집계로 표시하지 않습니다.</p></div>')+'<div class="detail-section"><h3>주간 리뷰 · 시간 보정</h3><p class="subtitle">예상 시간 대비 실제 시간 검토와 보정 설정을 유지합니다.</p><label class="check-field"><input type="checkbox" '+(prefsV2.calibration?'checked':'')+' onchange="prefsV2.calibration=this.checked;save()">시간 보정 사용 · UI 데모</label></div><div class="notice">위 수치는 이 HTML에서 조작한 예시 데이터입니다. 주간·월간·반복 통계의 실제 집계 로직을 재구현하거나 변경하지 않았습니다.</div>';};
openGuide=function(){modal(modalHead('원래 기능은 그대로, 정보 배치만 정돈')+'<p>pinit-fe의 화면과 기능 진입 경로를 확인해 만든 반응형 HTML 시안입니다. 실제 코드의 API·상태 전이·권한·반복 생성·통계 로직은 수정하지 않았습니다.</p><div class="detail-section"><h3>작업 카드</h3><p>마감은 오른쪽 상단, 중요도·난이도는 오른쪽 하단 원형 채움 표시로 배치합니다. 설명·예상 시간은 펼치기, 모든 정보와 수정·완료·일정 배정·삭제는 상세 화면에서 접근합니다.</p></div><div class="detail-section"><h3>화면 크기에 따른 배치</h3><p>데스크톱은 넓은 목록과 나란한 영역을, 모바일은 한 열과 하단 4개 탭·추가 버튼을 사용합니다. 설정·자동 계획·추가 버튼도 두 화면에서 접근할 수 있습니다.</p></div><div class="detail-section"><h3>기존 기능 범위</h3><p>검색·필터·정렬·태그·아카이브·의존성·일정 상태·날짜 이동·주/월 달력·생활 시간·반복 관리·휴지통·설정·통계 진입 경로를 유지합니다.</p></div><div class="notice">실제 서비스와 연결하지 않은 UI 데모입니다. 인증·푸시·AI 연결·자동 계획 엔진·반복 회차·기간 통계는 연결이 필요한 위치를 명시했습니다. 해당 기능의 완전한 재구현을 뜻하지 않습니다.</div><div class="dialog-actions"><button class="btn" onclick="resetDemo()">예시 데이터 초기화</button><button class="btn primary" onclick="closeModal()">확인</button></div>');};
resetDemo=function(){tasks=initial.map(t=>({...t,tags:[t.category],previous:t.id===4?[1]:[],next:t.id===1?[4]:[],archived:false}));scheduled=baseSchedulesV2.map(s=>({...s}));trashV2=[];seriesV2=[];tagsV2=['커리어','pinit','개인'];activeSchedule=null;save();closeModal();resetFiltersV2();navigate('today');resetDay();renderPlayerV2();toast('예시 데이터를 초기화했어요.');};
navigate=function(view){currentView=view;document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===view));const names={today:'오늘',tasks:'작업',schedules:'일정',statistics:'통계',settings:'설정',routines:'생활 시간',recurrences:'반복 관리',trash:'휴지통'};document.getElementById('crumb').textContent=names[view]||'오늘';document.getElementById('pageTitle').textContent={today:'오늘 할당된 일',tasks:'작업 목록',schedules:'일정',statistics:'통계',settings:'설정',routines:'생활 시간',recurrences:'반복 관리',trash:'휴지통'}[view];document.getElementById('pageSubtitle').textContent={today:'오늘 일정과 마감 작업, 바로 시작할 수 있는 작업을 확인하세요.',tasks:'필요한 작업을 찾고, 중요한 일부터 차근차근.',schedules:'주간·월간 달력에서 일정을 확인하고 진행 상태를 관리하세요.',statistics:'기존 기록과 집계 기준으로 나의 흐름을 돌아보세요.',settings:'알림·기준 정보·계정과 연결 설정을 관리하세요.',routines:'자동 계획에서 비워 둘 수면·식사·생활 시간을 정하세요.',recurrences:'반복 작업과 일정의 규칙을 관리하세요.',trash:'삭제한 작업과 일정을 다시 복원하세요.'}[view];const normal=['today','tasks','schedules'].includes(view),content=document.getElementById('content');content.className='content '+(view==='tasks'?'task-only':view==='schedules'?'schedule-only':['settings'].includes(view)?'settings-only':'');document.getElementById('primaryLayout').classList.toggle('hidden',!normal);document.getElementById('alternatePanel').classList.toggle('hidden',normal);document.querySelector('#taskPanel .filters').classList.add('hidden');document.querySelector('#taskPanel .panel-head .text-btn').classList.add('hidden');document.getElementById('taskToolbarV2').classList.toggle('hidden',view!=='tasks');document.querySelector('.head-actions').innerHTML=(['today','schedules','tasks'].includes(view)?'<button class="btn secondary" onclick="openPlanner()">'+icon('sparkles')+'하루 계획</button>':'<button class="btn secondary" onclick="navigate(\'settings\')">'+icon('left')+'설정</button>')+'<button class="btn primary" onclick="openAdd(\''+(view==='schedules'?'schedule':'task')+'\')">'+icon('plus')+(view==='schedules'?'일정 추가':'작업 추가')+'</button>';document.getElementById('taskHeading').innerHTML=(view==='today'?'오늘의 작업':'작업 목록')+' <span class="number" id="taskCount"></span>';if(view==='tasks')refreshToolbarV2();if(view==='settings')renderSettingsV2();if(view==='statistics')renderStats();if(view==='routines')renderRoutines();if(view==='recurrences')renderRecurrencesV2();if(view==='trash')renderTrashV2();renderTasks();renderTimeline();window.scrollTo(0,0);};
